function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
const z = require("zod");
if (!z.locales || typeof z.locales.ka !== "function") broken("z.locales.ka is missing");
z.config(z.locales.ka());
const r = z.string().safeParse(123);
if (r.success) broken("z.string() accepted a number");
const msg = r.error.issues[0].message;
if (msg.includes("\u10E1\u10E2\u10E0\u10D8\u10DC\u10D2\u10D8")) symptom("z.locales.ka names the expected type with the old word for string");
if (!msg.includes("\u10D5\u10D4\u10DA\u10D8")) broken("unexpected message: " + JSON.stringify(msg));
console.log("OK: z.locales.ka names the expected type with the new word for string");

